46	    private static HttpHeaders jsonHeaders(String requestId) {
47	        HttpHeaders headers = new HttpHeaders();
48	        headers.setContentType(MediaType.APPLICATION_JSON);
49	        if (requestId != null) {
50	            headers.set("X-Request-Id", requestId);
51	        }
52	        return headers;
