55	    private String registerBody(String name, int version, Object... dependencies) {
56	        Map<String, Object> body = new LinkedHashMap<>();
57	        body.put("name", name);
58	        body.put("version", version);
59	        body.put("dependencies", List.of(dependencies));
60	        return toJson(body);
61	    }
