63	    private Map<String, Object> dependency(String name, int min, int max) {
64	        Map<String, Object> dep = new LinkedHashMap<>();
65	        dep.put("name", name);
66	        dep.put("minimumVersion", min);
67	        dep.put("maximumVersion", max);
68	        return dep;
69	    }
70	
71	    private String toJson(Object value) {
72	        try {
73	            return new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(value);
74	        } catch (Exception e) {
75	            throw new IllegalStateException(e);
76	        }
77	    }
