79	    @Test
80	    void registerViaHttpReturns201AndReplaysWithSameRequestId() {
81	        String rid = UUID.randomUUID().toString();
82	        String body = registerBody("app", 1, dependency("lib", 1, 2));
83	        HttpEntity<String> request = new HttpEntity<>(body, jsonHeaders(rid));
84	
85	        ResponseEntity<JsonNode> first = restTemplate.postForEntity(
86	                "/api/artifacts", request, JsonNode.class);
87	        assertThat(first.getStatusCode()).isEqualTo(HttpStatus.CREATED);
88	        assertThat(first.getBody().path("name").asText()).isEqualTo("app");
89	        assertThat(first.getBody().path("version").asInt()).isEqualTo(1);
90	        assertThat(first.getBody().path("repositoryVersion").asLong()).isEqualTo(1L);
91	
92	        ResponseEntity<JsonNode> replay = restTemplate.postForEntity(
93	                "/api/artifacts", request, JsonNode.class);
94	        assertThat(replay.getStatusCode()).isEqualTo(HttpStatus.CREATED);
95	        assertThat(replay.getBody().path("createdAt").asText())
96	                .isEqualTo(first.getBody().path("createdAt").asText());
97	        assertThat(replay.getBody().path("repositoryVersion").asLong()).isEqualTo(1L);
98	    }
99	
100	    @Test
101	    void sameRequestIdDifferentPayloadReturns409() {
102	        String rid = UUID.randomUUID().toString();
103	        restTemplate.postForEntity("/api/artifacts",
104	                new HttpEntity<>(registerBody("app", 1), jsonHeaders(rid)), JsonNode.class);
105	
106	        ResponseEntity<JsonNode> conflict = restTemplate.postForEntity("/api/artifacts",
107	                new HttpEntity<>(registerBody("app", 2), jsonHeaders(rid)), JsonNode.class);
108	        assertThat(conflict.getStatusCode()).isEqualTo(HttpStatus.CONFLICT);
109	        assertThat(conflict.getBody().path("error").asText()).isEqualTo("CONFLICT");
110	    }
111	
112	    @Test
113	    void missingRequestIdHeaderReturns400() {
114	        ResponseEntity<JsonNode> response = restTemplate.postForEntity("/api/artifacts",
115	                new HttpEntity<>(registerBody("app", 1), jsonHeaders(null)), JsonNode.class);
116	        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
117	    }
118	
119	    @Test
120	    void invalidBeanReturns400() {
121	        // version 必须为正整数。
122	        Map<String, Object> body = Map.of("name", "app", "version", 0, "dependencies", List.of());
123	        ResponseEntity<JsonNode> response = restTemplate.postForEntity("/api/artifacts",
124	                new HttpEntity<>(toJson(body), jsonHeaders(UUID.randomUUID().toString())),
125	                JsonNode.class);
126	        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
127	    }
128	
129	    @Test
130	    void fullLockWorkflowAndHistoryQueries() {
131	        // app:1 -> lib[1,2]；lib2/lib1；锁定取 lib2。
132	        restTemplate.postForEntity("/api/artifacts",
133	                new HttpEntity<>(registerBody("app", 1, dependency("lib", 1, 2)),
134	                        jsonHeaders(UUID.randomUUID().toString())), JsonNode.class);
135	        restTemplate.postForEntity("/api/artifacts",
